// Guide me: deciding which element on the live page is the one a step was
// recorded on. Pure scoring, so it can be tested without a browser; the page
// side (src/extension/locator.ts) collects the same clues from each candidate.
import type { Locator } from './types'

// Ids and names that are generated by the page (and change every load) are
// useless as clues: numbers, long hex, React/Ember/Salesforce-style ids.
export function stableId(id: string | null | undefined): string | undefined {
  if (!id) return undefined
  const t = id.trim()
  if (!t || t.length > 80) return undefined
  if (/\d{3,}|[a-f0-9]{8,}|^:|^(ember|react|mui|j_id|uid|id-|input-|combobox-|radix-|headlessui-)/i.test(t)) return undefined
  return t
}

export const norm = (s: string | undefined) =>
  (s ?? '')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .replace(/[^\p{L}\p{N} ]/gu, '')
    .trim()

const same = (a?: string, b?: string) => !!a && !!b && norm(a) === norm(b) && norm(a) !== ''
const overlaps = (a?: string, b?: string) => {
  const x = norm(a)
  const y = norm(b)
  return x.length >= 3 && y.length >= 3 && (x.includes(y) || y.includes(x))
}

// How well a candidate matches the recorded clues. Higher is better.
export function scoreLocator(saved: Locator, cand: Locator): number {
  let score = 0
  if (saved.testId && saved.testId === cand.testId) score += 10
  if (saved.id && saved.id === cand.id) score += 8
  if (saved.name && saved.name === cand.name) score += 5
  if (same(saved.aria, cand.aria)) score += 5
  if (same(saved.label, cand.label)) score += 6
  else if (overlaps(saved.label, cand.label)) score += 2
  if (same(saved.text, cand.text)) score += 4
  if (same(saved.placeholder, cand.placeholder)) score += 3
  if (saved.href && saved.href === cand.href) score += 3
  if (same(saved.context, cand.context)) score += 3
  // The kind of element matters: a link isn't a field.
  if (saved.role || cand.role) score += saved.role === cand.role ? 2 : -2
  score += saved.tag === cand.tag ? 2 : -3
  if (saved.type && cand.type) score += saved.type === cand.type ? 1 : -3
  // Near where it was: up to 3 points, fading over a third of the page.
  if (saved.pageX !== undefined && saved.pageY !== undefined && cand.pageX !== undefined && cand.pageY !== undefined) {
    const d = Math.hypot(saved.pageX - cand.pageX, saved.pageY - cand.pageY)
    score += Math.max(0, 3 * (1 - d / 0.33))
  }
  return score
}

// Below this, a "match" is just an element of the same kind in roughly the
// same place, which is too weak to point a learner at.
export const MIN_SCORE = 8

// The best candidate, or -1 if none is good enough. Ties go to the first
// (candidates are passed in page order, after position has been scored).
export function pickBest(saved: Locator, cands: Locator[]): number {
  let best = -1
  let bestScore = MIN_SCORE - 0.001
  cands.forEach((c, i) => {
    const s = scoreLocator(saved, c)
    if (s > bestScore) {
      best = i
      bestScore = s
    }
  })
  return best
}
